command:
T=$(mktemp -d) && ../run.sh compile fixtures/interview-board.excalidraw $T/scene.yml | tee $T/compile.json && python3 - $T/compile.json $T/scene.yml <<'PYCODE'
import json,sys
receipt=json.load(open(sys.argv[1]))
scene=json.load(open(sys.argv[2]))
if receipt['schema']!='ops_excalidraw.compile.v1' or receipt['timeline_events']!=8:
    raise SystemExit(receipt)
recipes={event['recipe'] for event in scene['timeline']['events']}
for recipe in ['fade-slide-y','draw-stroke','halo-pulse','color-pin','pulse']:
    if recipe not in recipes:
        raise SystemExit(f'missing {recipe}')
print('OP_EXCALIDRAW_TIMELINE_OK', len(scene['timeline']['events']))
PYCODE
